using System.Windows;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.Views;public partial class DatabaseEditWindow:Window{readonly DatabaseResponse? existing;internal DatabaseEditWindow(DatabaseResponse? db=null){InitializeComponent();existing=db;if(db is null){HostBox.Text="localhost";PortBox.Text="1433";BackupBox.Text=@"D:\Backups\OdinVault";return;}NameBox.Text=db.Name;HostBox.Text=db.Host;PortBox.Text=db.Port?.ToString()??"";DatabaseBox.Text=db.DatabaseName;UsernameBox.Text=db.Username;TrustBox.IsChecked=db.TrustServerCertificate;EnabledBox.IsChecked=db.IsEnabled;BackupBox.Text=db.Policy?.BackupDirectory??"";MaxBox.Text=(db.Policy?.MaxLocalBackups??7).ToString();VerifyBox.IsChecked=db.Policy?.VerifyAfterBackup??true;Schedule.ScheduleCron=db.Policy?.ScheduleCron;}int? Port=>int.TryParse(PortBox.Text,out var p)?p:null;int Max=>int.TryParse(MaxBox.Text,out var n)&&n>0?n:7;string? Null(string s)=>string.IsNullOrWhiteSpace(s)?null:s.Trim();internal CreateDatabaseRequest CreateRequest=>new(NameBox.Text.Trim(),HostBox.Text.Trim(),Port,DatabaseBox.Text.Trim(),Null(UsernameBox.Text),Null(PasswordBox.Password),TrustBox.IsChecked==true,BackupBox.Text.Trim(),Max,VerifyBox.IsChecked==true,Schedule.ScheduleCron,EnabledBox.IsChecked==true);internal UpdateDatabaseRequest UpdateRequest=>new(NameBox.Text.Trim(),HostBox.Text.Trim(),Port,DatabaseBox.Text.Trim(),Null(UsernameBox.Text),Null(PasswordBox.Password),false,TrustBox.IsChecked==true,EnabledBox.IsChecked==true);internal UpdateBackupPolicyRequest PolicyRequest=>new(BackupBox.Text.Trim(),Max,VerifyBox.IsChecked==true,Schedule.ScheduleCron,EnabledBox.IsChecked==true);void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(NameBox.Text)||string.IsNullOrWhiteSpace(HostBox.Text)||string.IsNullOrWhiteSpace(DatabaseBox.Text)||string.IsNullOrWhiteSpace(BackupBox.Text)){System.Windows.MessageBox.Show(this,"نام، سرور، دیتابیس و مسیر بکاپ الزامی هستند.","OdinVault");return;}DialogResult=true;}}